/**
 * Runs the adversarial code reviewer the Development Workflow mandates, and
 * says plainly when it cannot.
 *
 * Three problems this solves that calling the plugin directly does not:
 *
 * - The reviewer lives at an absolute path under the caller's home directory,
 *   so a permission rule naming it works on one machine. This script is in the
 *   repository, so the rule that allows it is the same for everyone.
 * - The plugin may be absent — a fresh clone before the marketplace has been
 *   fetched, a teammate who declined the trust dialog, CI. That must be a
 *   documented fallback rather than an unexplained failure.
 * - The Codex CLI may be present but signed out, which fails differently and
 *   needs saying differently.
 *
 * Exit codes are the interface:
 *   0  the review ran; the reviewer's own verdict is in its output
 *   3  the reviewer is unavailable, and the reason is on stderr; the caller
 *      must fall back to the reviewer named in AGENTS.md step 8
 *   1  the review ran and failed, or something unexpected broke
 *
 * 3 is distinct on purpose: "nobody reviewed this" must never be mistaken for
 * "the review passed".
 */
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const UNAVAILABLE = 3;

/** The plugin supplying the reviewer, as `.claude/settings.json` enables it. */
const MARKETPLACE = 'openai-codex';
const PLUGIN = 'codex';

function fallback(reason) {
    console.error(`code-review: ${reason}`);
    console.error('code-review: falling back to the reviewer in AGENTS.md step 8.');
    process.exit(UNAVAILABLE);
}

/**
 * The newest installed copy of the plugin.
 *
 * Versions are directory names, so they are compared numerically rather than
 * as strings — otherwise 1.0.10 sorts below 1.0.9.
 */
function findCompanion() {
    const pluginRoot = path.join(os.homedir(), '.claude', 'plugins', 'cache', MARKETPLACE, PLUGIN);
    if (!fs.existsSync(pluginRoot)) return null;

    const versions = fs.readdirSync(pluginRoot, { withFileTypes: true })
        .filter((entry) => entry.isDirectory())
        .map((entry) => entry.name)
        .sort((left, right) => {
            const parse = (value) => value.split('.').map((part) => Number.parseInt(part, 10) || 0);
            const [a, b] = [parse(left), parse(right)];
            for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
                if ((a[i] ?? 0) !== (b[i] ?? 0)) return (b[i] ?? 0) - (a[i] ?? 0);
            }
            return 0;
        });

    for (const version of versions) {
        const companion = path.join(pluginRoot, version, 'scripts', 'codex-companion.mjs');
        if (fs.existsSync(companion)) return companion;
    }
    return null;
}

const companion = findCompanion();
if (companion === null) {
    fallback(`the ${PLUGIN}@${MARKETPLACE} plugin is not installed`);
}

// Readiness first, so an unusable reviewer is reported as unavailable rather
// than as a failed review. This probe does not spend Codex quota: it reads the
// CLI version and the cached credential without refreshing it.
const probe = spawnSync(process.execPath, [companion, 'setup', '--json'], { encoding: 'utf8' });
let readiness;
try {
    readiness = JSON.parse(probe.stdout);
} catch {
    fallback(`could not read the reviewer's readiness: ${(probe.stderr || probe.stdout || '').trim()}`);
}

if (readiness.ready !== true) {
    const detail = [readiness.codex?.detail, readiness.auth?.detail].filter(Boolean).join('; ');
    fallback(`the reviewer is installed but not ready${detail ? ` (${detail})` : ''}`);
}

// Everything after `--` is the reviewer's, so the caller can scope the review
// without this script knowing the plugin's flags.
const passthrough = process.argv.slice(2);
const review = spawnSync(
    process.execPath,
    [companion, 'adversarial-review', '--wait', ...passthrough],
    { stdio: 'inherit' },
);

process.exit(review.status ?? 1);

/** @jest-environment node */
import { execFileSync, spawnSync } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';

const repositoryRoot = path.resolve(__dirname, '../..');
const launcher = path.join(repositoryRoot, 'scripts', 'code-review.mjs');

/**
 * The reviewer the Development Workflow mandates is not always there — a fresh
 * clone before the marketplace is fetched, a declined trust dialog, CI, a
 * signed-out Codex CLI. What must never happen is that absence reading as a
 * clean review.
 *
 * So the launcher's exit codes are a contract, and this asserts the half that
 * can be tested without spending Codex quota: the unavailable path. The
 * available path runs a real review and costs money, so it is exercised by
 * actually using it, not by a test.
 */
const UNAVAILABLE = 3;

function runWithHome(home: string) {
    return spawnSync(process.execPath, [launcher], {
        encoding: 'utf8',
        env: { ...process.env, HOME: home },
        cwd: repositoryRoot,
    });
}

describe('the code review launcher', () => {
    let emptyHome: string;

    beforeAll(() => {
        emptyHome = fs.mkdtempSync(path.join(os.tmpdir(), 'review-launcher-'));
    });

    afterAll(() => {
        fs.rmSync(emptyHome, { recursive: true, force: true });
    });

    it('reports the reviewer as unavailable rather than failing silently', () => {
        const result = runWithHome(emptyHome);

        // Not 0, and not 1: a distinct code, so a caller can tell "nobody
        // reviewed this" from "the review passed" and from "the review ran and
        // found something".
        expect(result.status).toBe(UNAVAILABLE);
    });

    it('says why, and where to go instead', () => {
        const result = runWithHome(emptyHome);

        expect(result.stderr).toContain('not installed');
        // The fallback has to be nameable from the message alone: whoever hits
        // this is mid-workflow and needs to know the review still has to
        // happen, by some other route.
        expect(result.stderr).toMatch(/falling back/i);
        expect(result.stderr).toContain('AGENTS.md');
    });

    it('writes nothing to stdout when it cannot review', () => {
        // stdout carries the reviewer's own findings. Anything on it when no
        // review happened invites a caller to parse an empty verdict as a pass.
        const result = runWithHome(emptyHome);

        expect(result.stdout).toBe('');
    });

    it('is the command AGENTS.md tells an agent to run', () => {
        const agents = fs.readFileSync(path.join(repositoryRoot, 'AGENTS.md'), 'utf8');

        // The workflow naming a different path from the one that exists is the
        // failure this whole file guards against, one level up.
        expect(agents).toContain('node scripts/code-review.mjs');
        expect(fs.existsSync(launcher)).toBe(true);
    });

    it('is tracked, so a clone gets it', () => {
        const tracked = execFileSync('git', ['ls-files', '--', 'scripts/code-review.mjs'], {
            cwd: repositoryRoot,
            encoding: 'utf8',
        }).trim();

        expect(tracked).toBe('scripts/code-review.mjs');
    });
});

