/** @jest-environment node */
import { randomUUID } from 'crypto';
import fs from 'fs';
import path from 'path';
import { prisma } from '@/lib/prisma';
import { airportCodesForRoute } from '@/lib/airports';

const repositoryRoot = path.resolve(__dirname, '../..');

/**
 * A Playwright run starts from a known database, and against a server it
 * started itself.
 *
 * Both of these were false, and both produced failures that read as something
 * else. The suite booked seat 11A and never released it, so three specs failed
 * on that database from the first run onwards (#173). And `reuseExistingServer`
 * borrowed whatever was on the port, so a stale server made a healthy branch
 * look broken — and could equally make a broken one look healthy (#196).
 *
 * Neither is reachable from a unit test by running Playwright, so what is
 * asserted here is the two mechanisms: that the cleanup really removes a
 * booking and its seats, and that the config still refuses to reuse.
 */
const created = { flightIds: [] as number[], userIds: [] as string[] };

afterAll(async () => {
    await prisma.flight.deleteMany({ where: { id: { in: created.flightIds } } });
    await prisma.user.deleteMany({ where: { id: { in: created.userIds } } });
    await prisma.$disconnect();
});

describe('the state a Playwright run starts from', () => {
    it('clears a previous run\'s booking, and the seats it held', async () => {
        const flight = await prisma.flight.create({
            data: {
                flightNumber: `ISO-${randomUUID().slice(0, 8)}`,
                airline: 'Mona Airways',
                ...airportCodesForRoute('Seattle, USA', 'Detroit, USA'),
                departureDate: new Date(Date.now() + 20 * 24 * 60 * 60 * 1000),
                priceCents: 35_000,
            },
        });
        created.flightIds.push(flight.id);

        const user = await prisma.user.create({
            data: { id: `iso-${randomUUID()}`, email: `iso-${randomUUID()}@example.com` },
        });
        created.userIds.push(user.id);

        const booking = await prisma.booking.create({
            data: {
                userId: user.id,
                status: 'CONFIRMED',
                legs: { create: [{ sequence: 1, flightId: flight.id }] },
            },
        });
        await prisma.notification.create({
            data: { userId: user.id, title: 'Stale', message: 'From a previous run', type: 'SYSTEM' },
        });

        // What `e2e/global-setup.ts` does. Deleting the booking has to take the
        // legs with it, because a leg is what holds a seat.
        await prisma.booking.deleteMany();
        await prisma.notification.deleteMany();

        expect(await prisma.booking.findUnique({ where: { id: booking.id } })).toBeNull();
        expect(await prisma.itineraryLeg.count({ where: { flightId: flight.id } })).toBe(0);
        expect(await prisma.notification.count({ where: { userId: user.id } })).toBe(0);

        // And it must not take the seeded inventory with it, or the next run
        // has nothing to book.
        expect(await prisma.flight.count()).toBeGreaterThan(0);
        expect(await prisma.airport.count()).toBeGreaterThan(0);
        expect(await prisma.flightSchedule.count()).toBeGreaterThan(0);
        // Nor the account someone signed in with by hand.
        expect(await prisma.user.findUnique({ where: { id: user.id } })).not.toBeNull();
    });

    it('leaves nothing for the seat map to render as taken', async () => {
        // The concrete symptom of #173: 11A already sold on a seeded flight.
        const held = await prisma.seatAssignment.count({ where: { seatNumber: '11A' } });

        expect(held).toBe(0);
    });

    it('starts its own server rather than borrowing one', () => {
        // A one-word regression here is invisible until a run lies to someone
        // (#196), so it is pinned rather than trusted.
        const config = fs.readFileSync(path.join(repositoryRoot, 'playwright.config.ts'), 'utf8');

        expect(config).toMatch(/reuseExistingServer:\s*false/);
        expect(config).not.toMatch(/reuseExistingServer:\s*!process\.env\.CI/);
    });
});

