import { registerAndSignIn } from './helpers/auth';

test('a signed-in client whose server is unreachable still reports it', async ({ page }) => {
  test.slow();
  const errors: string[] = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });

  await registerAndSignIn(page, {
    name: 'Probe User',
    email: `probe212-${Date.now()}@example.com`,
    password: 'ProbePassword123!',
  });
  await page.goto('/profile');
  await expect(page.getByLabel('Toggle notifications')).toBeVisible();

  errors.length = 0;
  // The server becomes unreachable while the page stays put: no navigation, no
  // unmount. This is exactly #212's scenario.
  await page.route('**/profile', (route) => route.abort('failed'));
  await page.route('**/*', (route) => {
    if (route.request().method() === 'POST') return route.abort('failed');
    return route.continue();
  });

  await page.waitForTimeout(7000);   // two or three poll ticks
  console.log('[probe] console errors seen:', JSON.stringify(errors.slice(0, 4)));
  expect(errors.some((e) => /Failed to load notifications/i.test(e))).toBe(true);
});
EOF
