async function reportLeakedRows(): Promise<string | null> {
  const before = readRunBaseline();
  if (!before) {
    // Not fatal: `global-setup` records this before it can fail, so an absent
    // baseline means it never ran at all, and whatever stopped it is the error
    // worth reading. Said out loud because a silent skip is how a guard becomes
    // decoration.
    console.warn(
      '[global-teardown] No baseline was recorded, so this run was not checked for '
      + 'leftover rows (#213).'
    );
    return null;
  }

  return describeLeakedRows(rowsAddedDuringRun(before, await captureRowSnapshot()));
}

input.new_string:
async function reportLeakedRows(): Promise<string | null> {
  const before = readRunBaseline();
  if (!before) {
    // Fatal, rather than a warning and a skip. An absent baseline is not a
    // clean run, it is an unchecked one, and the difference is invisible in a
    // green result -- which is how a guard becomes decoration. Playwright does
    // not reach teardown at all when `global-setup` throws, so this cannot mask
    // a real setup failure: it means the recording was removed.
    throw new Error(
      'This run was not checked for leftover rows, because no baseline was recorded: '
      + '`global-setup` must call `recordRunBaseline(await captureRowSnapshot())` before '
      + 'the tests begin (#213).'
    );
  }

  return describeLeakedRows(rowsAddedDuringRun(before, await captureRowSnapshot()));
}

