83	const RELATION = /relation \\?"([A-Za-z0-9_]+)\\?"/;
84	const CONSTRAINT = /constraint \\?"([A-Za-z0-9_]+)\\?"/;
85	/** `Unique constraint failed on the fields: (`email`)` — no SQLSTATE at all. */
86	const UNIQUE_FIELDS = /Unique constraint failed on the fields?: \(([^)]*)\)/;
87	/**
88	 * Prisma 5 says `Foreign key constraint violated: `X (index)``; older wording
89	 * was `failed on the field:`. Neither string exists in the JS runtime — they
90	 * come from the Rust engine, so both are kept.
91	 */
92	const FOREIGN_KEY = /Foreign key constraint (?:violated|failed on the field):\s*`?([A-Za-z0-9_]+)/;
93	
94	function firstMatch(pattern: RegExp, message: string): string | null {
95	    return pattern.exec(message)?.[1] ?? null;
96	}
97	
98	/**
99	 * Keeps only what is shaped like a bare identifier.
100	 *
101	 * This is a filter on shape, not on provenance: it drops anything carrying `@`,
102	 * `.`, `-`, `/` or whitespace, which is what makes an email address — the #142
103	 * payload — unable to pass. An identifier-shaped secret such as a cuid or a hex
104	 * digest fits the shape, so this is not a boundary either; `beforeRowData` is
105	 * what keeps values out, and #163 covers the rest.
106	 */
107	function identifiers(captured: string | null): string[] | null {
108	    if (captured === null) return null;
109	    const names = captured
110	        .split(',')
111	        .map((name) => name.trim().replace(/[`"]/g, ''))
112	        .filter((name) => /^[A-Za-z0-9_]+$/.test(name));
113	    return names.length > 0 ? names : null;
114	}
115	
116	/**
117	 * Builds the record that is safe to write for a Prisma warning or error.
118	 *
119	 * A Postgres error embeds the offending row in its `detail` — the observed case
120	 * was a customer's email address on stdout in production (#142) — so the record
121	 * is assembled from named fields rather than filtered down from the message.
122	 * Anything not on this list is dropped, including the message itself: an
123	 * unrecognised failure may carry anything, and a whitelist is the only form of
124	 * this that stays correct as Prisma's wording changes.
125	 *
126	 * The cost is real. An operator gets the code, the relation, the constraint and
127	 * the columns, which is enough to identify a failure but not to read the values
128	 * behind it. Reproducing with data is a development-environment job, where
129	 * `query` logging is still on and the data is seeded.
130	 *
131	 * Warnings go through the same treatment, which looks over-cautious given they
132	 * are engine and client messages rather than query results. They are not
133	 * exempt: Prisma interpolates an arbitrary upstream message into its retry
134	 * warning, and it puts connection identity into log text elsewhere — a failed
135	 * connection names the database user. There is no level that is safe by
136	 * default, so none is treated as one.
137	 */
138	export function redactPrismaLogEvent(
139	    level: PrismaLogLevel,
140	    event: PrismaLogEvent,
141	): RedactedPrismaLogRecord {
142	    const safe = beforeRowData(event.message);
143	    const fields = identifiers(firstMatch(UNIQUE_FIELDS, safe));
144	
145	    return {
146	        level,
147	        timestamp: event.timestamp,
148	        target: event.target,
149	        // Prisma states the code in its own vocabulary for the two forms that
150	        // carry no SQLSTATE, so those are read from the wording it controls.
151	        code:
152	            firstMatch(CODE, safe)
153	            ?? firstMatch(PRISMA_CODE, safe)
154	            ?? (fields ? 'P2002' : null)
155	            ?? (FOREIGN_KEY.test(safe) ? 'P2003' : null),
156	        relation: firstMatch(RELATION, safe),
157	        constraint: firstMatch(CONSTRAINT, safe) ?? firstMatch(FOREIGN_KEY, safe),
158	        fields,
159	    };
160	}
161	
162	/**
163	 * Prisma's `query` log writes each statement's bind parameters, which include
164	 * customer email addresses and token digests. Keep it for local development,
165	 * where the visibility is useful and the data is seeded, and keep it out of
166	 * every other environment.
167	 *
168	 * Warnings and errors are always reported, but never by Prisma itself outside
169	 * development: it is handed an event emitter so the payload passes through
170	 * `redactPrismaLogEvent` before anything is written.
171	 */
172	function createPrismaClient(): PrismaClient {
173	    if (isDevelopment) {
174	        const developmentLog: Prisma.LogLevel[] = ['query', 'warn', 'error'];
175	        return new PrismaClient({ log: developmentLog });
176	    }
177	
178	    const client = new PrismaClient({
179	        log: [
180	            { emit: 'event', level: 'warn' },
181	            { emit: 'event', level: 'error' },
182	        ],
183	    });
184	
185	    client.$on('warn', (event) => {
186	        console.warn(redactPrismaLogEvent('warn', event));
187	    });
188	    client.$on('error', (event) => {
189	        console.error(redactPrismaLogEvent('error', event));
190	    });
191	
192	    return client;
193	}
194	
195	export const prisma = globalForPrisma.prisma ?? createPrismaClient();
196	
197	if (process.env.NODE_ENV !== 'production') globalForPrisma.prisma = prisma;
