/** @jest-environment node */
import {
    airportLocalInstant,
    departureInOriginZone,
} from '@/lib/flightTime';

/**
 * Turning an airport's wall clock into an instant, and back again for display.
 *
 * `Flight.departureDate` was neither. `FlightScheduleService` built it as the
 * schedule's local time with a `Z` stapled on -- 08:00 in Tokyo stored as
 * 08:00Z, which is 17:00 in Tokyo -- and every screen then rendered it with
 * `toLocaleDateString()`, in whatever timezone the viewer's browser happened to
 * be in. Two errors that cancel only for a viewer sitting in UTC looking at a
 * UTC airport (#84).
 *
 * The comparisons cared as much as the displays: the cancellation guard added
 * in #76 refuses a booking whose flight has departed, and east of UTC it was
 * wrong by the origin's offset -- nine hours during which a flown flight could
 * still be cancelled.
 */
describe('an airport wall clock becomes an instant', () => {
    it('reads a time as local to the airport, not as UTC', () => {
        // 08:00 in Tokyo is 23:00 the previous day in UTC. Stapling a Z on
        // gave 08:00Z, nine hours late and, for this flight, the wrong day.
        expect(airportLocalInstant('2026-08-16', '08:00', 'Asia/Tokyo').toISOString())
            .toBe('2026-08-15T23:00:00.000Z');
    });

    it('handles a zone behind UTC', () => {
        // Seattle in August is UTC-7.
        expect(airportLocalInstant('2026-08-16', '08:00', 'America/Los_Angeles').toISOString())
            .toBe('2026-08-16T15:00:00.000Z');
    });

    it('is the identity for UTC itself', () => {
        expect(airportLocalInstant('2026-08-16', '08:00', 'UTC').toISOString())
            .toBe('2026-08-16T08:00:00.000Z');
    });

    it('follows the zone across a daylight-saving change', () => {
        // The same wall clock either side of the US autumn transition is a
        // different instant, and a single fixed offset gets one of them wrong.
        expect(airportLocalInstant('2026-10-30', '08:00', 'America/New_York').toISOString())
            .toBe('2026-10-30T12:00:00.000Z');
        expect(airportLocalInstant('2026-11-05', '08:00', 'America/New_York').toISOString())
            .toBe('2026-11-05T13:00:00.000Z');
    });

    it('resolves a wall clock that daylight saving skips', () => {
        // 02:30 on the spring-forward morning never happens in New York. There
        // is no right answer, only a defined one: it must not throw, and it
        // must land on a real instant near the gap.
        const instant = airportLocalInstant('2026-03-08', '02:30', 'America/New_York');

        expect(Number.isNaN(instant.getTime())).toBe(false);
        expect(instant.toISOString()).toBe('2026-03-08T07:30:00.000Z');
    });

    it('resolves a wall clock daylight saving repeats', () => {
        // 01:30 happens twice on the autumn morning. The earlier of the two is
        // the conventional reading, and the only one a schedule could mean
        // without saying which.
        expect(airportLocalInstant('2026-11-01', '01:30', 'America/New_York').toISOString())
            .toBe('2026-11-01T05:30:00.000Z');
    });

    it('is exactly reversible for an ordinary time', () => {
        for (const zone of ['Asia/Tokyo', 'America/Los_Angeles', 'Europe/London', 'UTC']) {
            const instant = airportLocalInstant('2026-06-15', '14:45', zone);
            expect(departureInOriginZone(instant, zone).time).toBe('14:45');
        }
    });
});

describe('and an instant reads back as the airport saw it', () => {
    const tokyoDeparture = new Date('2026-08-15T23:00:00.000Z');

    it('gives the date and time at the origin, not at the viewer', () => {
        // The whole point: this is 15 August in UTC and 16 August in Tokyo,
        // and the flight leaves on the 16th.
        expect(departureInOriginZone(tokyoDeparture, 'Asia/Tokyo')).toMatchObject({
            date: '2026-08-16',
            time: '08:00',
        });
    });

    it('names the zone, so the time is not just a number', () => {
        // A customer cannot tell which clock a bare "08:00" is on.
        expect(departureInOriginZone(tokyoDeparture, 'Asia/Tokyo').zoneLabel).toBe('GMT+9');
        expect(departureInOriginZone(new Date('2026-08-16T15:00:00.000Z'), 'America/Los_Angeles').zoneLabel)
            .toBe('PDT');
    });

    it('reports the zone that was in force, not the one in force now', () => {
        // Same airport, either side of a transition.
        const summer = departureInOriginZone(new Date('2026-08-16T12:00:00.000Z'), 'America/New_York');
        const winter = departureInOriginZone(new Date('2026-12-16T13:00:00.000Z'), 'America/New_York');

        expect(summer.zoneLabel).toBe('EDT');
        expect(winter.zoneLabel).toBe('EST');
    });

    it('formats a date a customer would recognise', () => {
        expect(departureInOriginZone(tokyoDeparture, 'Asia/Tokyo').readableDate)
            .toBe('Aug 16, 2026');
    });

    it('falls back to UTC when the zone is unknown rather than throwing', () => {
        // A place with no airport record should degrade to the old behaviour,
        // not take a page down.
        expect(departureInOriginZone(tokyoDeparture, null)).toMatchObject({
            date: '2026-08-15',
            time: '23:00',
        });
    });
});

/**
 * When a flight leaves, in the only two forms that are ever correct: an instant
 * to compare, and an airport's local reading to show.
 *
 * `Flight.departureDate` used to be neither. `FlightScheduleService` built it
 * from the schedule's local time with a `Z` stapled on -- 08:00 in Tokyo stored
 * as 08:00Z, which is 17:00 in Tokyo -- and every screen rendered it with
 * `toLocaleDateString()`, in whatever timezone the viewer's browser happened to
 * be in. Two errors that cancel only for a viewer in UTC looking at a UTC
 * airport, which is why they survived so long (#84).
 *
 * The comparisons cared as much as the displays. #76's cancellation guard
 * refuses a booking whose flight has departed; east of UTC it was wrong by the
 * origin's offset, leaving hours in which a flown flight could still be
 * cancelled -- releasing a seat that was used and taking back the points for a
 * trip the customer took.
 *
 * Everything here goes through `Intl`, which carries the IANA database and its
 * history of transitions, so a fixed offset per airport is never assumed.
 */

/**
 * How far the zone is from UTC at a given instant, in milliseconds.
 *
 * Read by asking `Intl` what the wall clock says there and subtracting: there
 * is no API that answers directly, and hard-coding offsets would be wrong twice
 * a year for most of the world.
 */
function zoneOffsetMs(timeZone: string, instant: Date): number {
    const parts = new Intl.DateTimeFormat('en-US', {
        timeZone,
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
    }).formatToParts(instant);

    const at = (type: Intl.DateTimeFormatPartTypes) =>
        Number(parts.find(part => part.type === type)!.value);

    // `hour` comes back as 24 at midnight under hour12: false, which Date.UTC
    // rolls into the next day -- correct arithmetic, wrong day.
    const asIfUtc = Date.UTC(
        at('year'), at('month') - 1, at('day'), at('hour') % 24, at('minute'), at('second'),
    );
    return asIfUtc - instant.getTime();
}

/**
 * The instant at which a wall clock reads `date` `time` at that airport.
 *
 * Two passes, because the offset depends on the instant and the instant depends
 * on the offset. The first pass guesses using the offset in force at the same
 * wall clock read as UTC; the second corrects it using the offset actually in
 * force at the guessed instant. That is exact everywhere except inside a
 * daylight-saving transition, where the answer is a choice rather than a fact:
 *
 *   * A wall clock the change *skips* (02:30 on a spring-forward morning) never
 *     happens. This lands just after the gap rather than throwing -- a schedule
 *     that names it is a data problem, not a reason to fail a page.
 *   * A wall clock the change *repeats* (01:30 on an autumn morning) happens
 *     twice. This takes the earlier, which is the conventional reading and the
 *     only one a schedule can mean without saying which.
 */
export function airportLocalInstant(date: string, time: string, timeZone: string): Date {
    const asIfUtc = Date.parse(`${date}T${time}:00.000Z`);
    if (Number.isNaN(asIfUtc)) {
        throw new Error(`Not a date and time this can read: ${date} ${time}`);
    }

    const firstGuess = new Date(asIfUtc - zoneOffsetMs(timeZone, new Date(asIfUtc)));
    return new Date(asIfUtc - zoneOffsetMs(timeZone, firstGuess));
}

/** A departure as the airport it leaves from sees it. */
export interface LocalDeparture {
    /** `YYYY-MM-DD` at the origin, for comparing and for date inputs. */
    date: string;
    /** `HH:MM` on the origin's 24-hour clock. */
    time: string;
    /** `Aug 16, 2026`, for reading. */
    readableDate: string;
    /** `PDT`, `GMT+9` -- whatever that zone was called at that instant. */
    zoneLabel: string;
}

const READABLE_DATE: Intl.DateTimeFormatOptions = {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
};

/**
 * A departure instant, read in the origin airport's timezone.
 *
 * `timeZone` is null for a place with no airport record, which falls back to
 * UTC -- the same answer the application gave everywhere before, and a
 * degradation rather than a failure.
 *
 * The zone label matters as much as the time. A bare "08:00" on a booking is
 * not information: the customer cannot tell whose clock it is on, and for an
 * international leg the answer is rarely theirs.
 */
export function departureInOriginZone(
    departure: Date | string,
    timeZone: string | null | undefined,
): LocalDeparture {
    const instant = departure instanceof Date ? departure : new Date(departure);
    const zone = timeZone ?? 'UTC';

    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: zone,
        hour12: false,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
    }).formatToParts(instant);
    const at = (type: Intl.DateTimeFormatPartTypes) =>
        parts.find(part => part.type === type)!.value;

    const hour = String(Number(at('hour')) % 24).padStart(2, '0');

    return {
        date: `${at('year')}-${at('month')}-${at('day')}`,
        time: `${hour}:${at('minute')}`,
        readableDate: new Intl.DateTimeFormat('en-US', { ...READABLE_DATE, timeZone: zone })
            .format(instant),
        zoneLabel: new Intl.DateTimeFormat('en-US', { timeZone: zone, timeZoneName: 'short' })
            .formatToParts(instant)
            .find(part => part.type === 'timeZoneName')!.value,
    };
}

