cat >> app/globals.css <<'EOF'

/*
 * The bookings table, stacked into cards on a narrow screen (#240).
 *
 * The table needs about 580px to lay out and a phone gives it 316, so
 * everything past the flight number sat behind a sideways scroll the customer
 * had no way to discover: no scrollbar gutter, and where a thumb is drawn it is
 * #2b2640 on #0d0c14, roughly 1.4:1. A disrupted booking could say "your seat
 * is held, cancel for a full refund" with the Cancel button 173px beyond the
 * right edge.
 *
 * Restyling the one table rather than rendering a second card tree is
 * deliberate. Two trees means two copies of every locator and every assertion,
 * and a duplicated status is exactly what put an aria-hidden copy in front of a
 * test in #243. There is one DOM here at every width.
 *
 * The cost is that below the breakpoint this stops being a table for assistive
 * technology -- `display: block` drops the row and cell roles. That is the
 * trade the pattern makes: the header row is replaced by a label on each cell,
 * so every value still arrives named, which is what the header was for.
 */
.booking-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

@media (max-width: 640px) {
  .bookings-table,
  .bookings-table tbody,
  .bookings-table tr,
  .bookings-table td {
    display: block;
    width: auto;
  }

  /* Off-screen rather than `display: none`: the headings still name the
     columns for anything reading the table linearly. */
  .bookings-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .bookings-table tbody {
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    background-color: rgba(255, 255, 255, 0.02);
    padding: 12px;
    margin-bottom: 12px;
  }

  .bookings-table td {
    padding: 2px 0;
    text-align: left;
  }

  /* What the column heading used to say, now said per value. Without this a
     stacked row is a column of unlabelled strings. */
  .bookings-table td[data-label]::before {
    content: attr(data-label);
    display: block;
    font-size: 0.65rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: rgba(255, 255, 255, 0.55);
  }

  /* A rowSpan cell renders once per booking; the leg rows that do not carry it
     would otherwise leave a labelled blank. */
  .bookings-table td:empty {
    display: none;
  }

  .bookings-table .booking-actions {
    justify-content: flex-start;
    margin-top: 8px;
  }

  /* 12px text in 4px of padding is a 20px target. Thumbs need more. */
  .bookings-table .booking-actions button {
    padding: 10px 14px;
    font-size: 14px;
    min-height: 44px;
  }
}
