cat >> app/globals.css <<'EOF'
/*
 * The bookings table, stacked into cards on a narrow screen (#240).
 *
 * The table needs 590px to lay out and a phone gives it 316, so everything past
 * the flight number sat behind a sideways scroll the customer had no way to
 * discover: no scrollbar gutter, and where a thumb is drawn it is #2b2640 on
 * #0d0c14, roughly 1.4:1. A disrupted booking could say "your seat is held,
 * cancel for a full refund" with the Cancel button 173px beyond the right edge.
 *
 * Restyling the one table rather than rendering a second card tree is
 * deliberate. Two trees means two copies of every locator and every assertion,
 * and a duplicated status is what put an aria-hidden copy in front of a test in
 * #243. There is one DOM here at every width.
 *
 * The breakpoint is 767px, not 640px, and the difference is the whole defect.
 * At 640 the region is 534px wide and the table wants 590, so 641-699px kept
 * the sideways scroll: measured at 667 -- an iPhone SE in landscape, or a
 * window snapped to half a 1366 laptop -- the Cancel button rendered clipped
 * mid-word as "Ca". A breakpoint below the table's natural width does not
 * remove the overflow, it relocates it. 767 is the widest viewport that can
 * still be narrower than the table, so nothing is left between them.
 */
.booking-actions {
  display: flex;
  gap: 8px;
  justify-content: flex-end;
}

/* Eyes only, and only when stacked: the header row is still read out. */
.cell-label {
  display: none;
}

@media (max-width: 767px) {
  .bookings-table,
  .bookings-table td {
    display: block;
    width: auto;
  }

  /*
   * Every cell of a booking becomes a direct child of one column, whichever row
   * it was written in. `rowSpan` stops meaning anything once rows are blocks,
   * so Price, Status and Actions -- authored inside the first leg's row for the
   * table -- landed in the middle of the card, and a round trip printed its
   * second leg *after* the buttons. The card then said "MA404 cancelled by
   * airline" above a block naming MA102, with MA404 trailing below the action.
   */
  .bookings-table tbody {
    display: flex;
    flex-direction: column;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    background-color: rgba(255, 255, 255, 0.02);
    padding: 12px;
    margin-bottom: 12px;
  }

  .bookings-table tbody tr {
    display: contents;
  }

  /* Itinerary first, then what the booking costs, what happened to it, and
     what can be done about it. Unset cells keep source order at 0. */
  .bookings-table td[data-label='Price'] { order: 1; }
  .bookings-table td[data-label='Status'] { order: 2; }
  .bookings-table .booking-actions-cell { order: 3; }

  /* Off-screen rather than `display: none`: the headings still name the
     columns for anything reading the table linearly. */
  .bookings-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }

  .bookings-table td {
    padding: 2px 0;
    text-align: left;
    /* `.profile td` draws a row separator, which under `display: block` became
       a rule between every stacked value -- including one between the
       disruption note and the button that answers it. */
    border-top: 0;
  }

  .cell-label {
    display: block;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: rgba(255, 255, 255, 0.55);
  }

  /* A leg after the first starts a new group within the card. The table hid
     this separator to keep legs joined under their spanned cells; stacked,
     the legs are what needs telling apart. */
  .bookings-table tr[data-continues-booking] td[data-label='Flight'] {
    margin-top: 10px;
    padding-top: 10px;
    border-top: 1px solid rgba(255, 255, 255, 0.08);
  }

  /* A booking that cannot be cancelled renders the actions cell empty. */
  .bookings-table td:empty {
    display: none;
  }

  .bookings-table .booking-actions {
    justify-content: flex-start;
    margin-top: 12px;
  }

  /* 12px in 4px of padding is a 20px target. Thumbs need more, and these
     declarations only reach the button because the inline padding and
     font-size were removed from the JSX -- inline styles outrank a rule. */
  .bookings-table .booking-actions button {
    padding: 10px 14px;
    font-size: 14px;
    min-height: 44px;
  }
}
EOF
